SELECT MIN(`Low Grade`) AS LowestGrade
FROM schools
WHERE NCESDist = '0632640';

SELECT ROUND(SUM(CASE WHEN T2.language = 'Simplified Chinese' THEN 1 ELSE 0 END) * 100.0 / COUNT(T1.uuid), 2) AS percentage
FROM cards AS T1
LEFT JOIN foreign_data AS T2 ON T1.uuid = T2.uuid;

SELECT COUNT(*) 
FROM rulings 
WHERE uuid = (SELECT uuid FROM cards WHERE name = 'Mishra''s Factory' ORDER BY multiverseId DESC LIMIT 1);

SELECT COUNT(*) 
FROM cards 
WHERE hasContentWarning = 1 AND availability = 'paper' AND mtgoId IS NULL;

SELECT COUNT(DISTINCT uuid) 
FROM cards 
WHERE frameVersion >= '2015' AND text IS NOT NULL;

SELECT COUNT(DISTINCT printings) AS total_printings
FROM cards
WHERE power > 3 AND power <= 10;

SELECT ViewCount, LastEditorDisplayName 
FROM posts 
WHERE Title = 'Computer game datasets';

SELECT MIN(Id) 
FROM users 
WHERE DisplayName = 'Michael';

SELECT ROUND((AVG(CASE WHEN T1.defensive_work_rate IN ('Low', 'Medium', 'High') THEN T1.overall_rating ELSE NULL END) - (SELECT overall_rating FROM Player_Attributes WHERE date = '2013-07-12' AND player_api_id = (SELECT player_api_id FROM Player WHERE player_name = 'Landon Donovan'))) / (SELECT overall_rating FROM Player_Attributes WHERE date = '2013-07-12' AND player_api_id = (SELECT player_api_id FROM Player WHERE player_name = 'Landon Donovan')) * 100, 2) AS percentage_increase
FROM Player_Attributes AS T1
WHERE T1.date = '2013-07-12';

SELECT ROUND(SUM(CASE WHEN T1.major_id IS NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(T2.major_id), 2) AS percentage
FROM major AS T1
LEFT JOIN member AS T2 ON T1.major_id = T2.link_to_major;

SELECT superhero_name 
FROM superhero 
WHERE height_cm BETWEEN 170 AND 190 AND eye_colour_id IS NULL;

SELECT COUNT(DISTINCT publisher_id) 
FROM superhero 
WHERE height_cm > 200;

SELECT COUNT(DISTINCT T1.ID) AS ThrombosisPatientCount
FROM Examination AS T1
WHERE T1.Thrombosis = 1 AND T1.`Examination Date` BETWEEN '1997-01-01' AND '1997-12-31';
